/* Determinism check for Game Boy / Game Boy Color cores: fixed ROM (generated by make_gb_rom.py), scripted inputs,
 * virtual RTC. Prints a CRC32 over the complete save state and the framebuffer at fixed frames. The expected values must
 * be identical on every platform and architecture (CI runs this binary through the Java GbDeterminismCheck on
 * Linux, Windows, macOS arm64 and macOS x86_64, which prints the same numbers).   test_determinism_gb <gb-rom-dir> */
#include "gbacore.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static uint32_t crc_table[256];
static void crc_init(void) {
	for (uint32_t i = 0; i < 256; ++i) {
		uint32_t c = i;
		for (int k = 0; k < 8; ++k) c = (c & 1) ? 0xEDB88320u ^ (c >> 1) : c >> 1;
		crc_table[i] = c;
	}
}
static uint32_t crc_update(uint32_t crc, const uint8_t* p, size_t n) {
	crc = ~crc;
	while (n--) crc = crc_table[(crc ^ *p++) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

/* same script as the Java check: a pseudo random key set that changes every 16 frames */
static int script(long long frame) {
	long long block = frame / 16;
	uint64_t h = ((uint64_t) (block + 1) * 0x9E3779B97F4A7C15ull) ^ ((uint64_t) (42 * 31 + 7) * 0xC2B2AE3D27D4EB4Full);
	h ^= h >> 29;
	h *= 0xBF58476D1CE4E5B9ull;
	h ^= h >> 32;
	return (int) (h & 0xFFull);
}

struct Case { const char* rom; uint32_t expect[3]; };
static const int g_frames[3] = { 100, 1000, 1500 };

int main(int argc, char** argv) {
	if (argc < 2) return 2;
	crc_init();
	static const struct Case cases[2] = {
		{ "gb_dmg.gb", { 0x2337af15u, 0x61e462e8u, 0xbe93eab3u } },
		{ "gb_cgb.gbc", { 0x5cbba67au, 0xca63c874u, 0x20b6c3b1u } } };
	int fail = 0;
	for (int k = 0; k < 2; ++k) {
		char path[1024];
		snprintf(path, sizeof(path), "%s/%s", argv[1], cases[k].rom);
		gba_core* c = gba_create();
		if (!c || gba_load_rom(c, path) != 0) { printf("cannot load %s\n", path); return 2; }
		gba_set_rtc(c, 1760000000, GBA_RTC_VIRTUAL);
		int next = 0;
		for (long long f = 0; f < 1500; ++f) {
			gba_set_keys(c, (uint32_t) script(f));
			if (gba_run_frame(c) != GBA_RUN_FRAME_DONE) { printf("run error\n"); return 1; }
			int16_t pcm[4096];
			while (gba_read_audio(c, pcm, 2048) > 0) { }
			if (next < 3 && f + 1 == g_frames[next]) {
				size_t n = gba_state_size(c);
				uint8_t* st = malloc(n);
				if (gba_save_state(c, st, n) != n) { printf("save state failed\n"); return 1; }
				uint32_t h = crc_update(0, st, n);
				h = crc_update(h, gba_framebuffer(c), (size_t) gba_frame_width(c) * gba_frame_height(c) * 4);
				free(st);
				printf("%s f=%d all=%08x %s\n", cases[k].rom, g_frames[next], h, h == cases[k].expect[next] ? "ok" : "MISMATCH");
				if (h != cases[k].expect[next]) fail = 1;
				++next;
			}
		}
		gba_destroy(c);
	}
	return fail;
}
